# "es"/"de" above are matched to "fr"'s keys purely by position (dict(zip(...))
# stops silently at whichever side runs out first) -- a key added to "fr"
# without a same-position value added to both tuples desyncs every entry
# after it, producing wrong-but-present translations that tr()'s
# missing-key fallback can't catch. This turns that into a loud failure
# instead of a silent one next time it happens.
_missing_es = set(_KEYS) - set(EXTRA_TRANSLATIONS["es"])
_missing_de = set(_KEYS) - set(EXTRA_TRANSLATIONS["de"])
if _missing_es or _missing_de:
    raise ValueError(
        "i18n_catalog.py: the es/de positional-zip translation tuples are out of "
        f"sync with fr's keys (missing in es: {sorted(_missing_es)}; missing in "
        f"de: {sorted(_missing_de)}). A value was added to fr without a matching "
        "value added at the same position in both the es and de tuples."
    )
del _KEYS, _missing_es, _missing_de

